def solve(alpha_A: float, beta_A: float, alpha_B: float, beta_B: float, n_samples: int = 10000) -> float:
    import random
    rng = random.Random(42)
    # For each sample, draw one theta from each posterior and check which is larger.
    # The fraction of samples where A > B estimates P(theta_A > theta_B).
    count = sum(
        1 for _ in range(n_samples)
        if rng.betavariate(alpha_A, beta_A) > rng.betavariate(alpha_B, beta_B)
    )
    return round(count / n_samples, 4)

