solution_code:
def solve(k: int, lam: float) -> float:
    import math
    if k < 0:
        raise ValueError('k must be non-negative')
    if lam <= 0:
        raise ValueError('lambda must be positive')
    # P(X = k) = e^{-lambda} * lambda^k / k!
    return round(math.exp(-lam) * (lam ** k) / math.factorial(k), 6)
